"# TriageNet — Nginx TLS (HTTPS) Configuration
# This file is loaded alongside default.conf in production when
# TLS certificates are available from Let's Encrypt / Certbot.
#
# Provides:
#   - HTTPS on port 443 with TLS 1.2/1.3
#   - HTTP → HTTPS redirect on port 80
#   - Let's Encrypt ACME challenge route for certificate renewal
#   - HSTS with 1-year max-age
#   - OCSP stapling for certificate validation performance
#   - Modern cipher suite (Mozilla Intermediate compatibility)

# HTTP → HTTPS redirect + ACME challenge
server {
    listen 80;
    server_name ${DEPLOY_DOMAIN};

    # Let's Encrypt ACME challenge (must remain accessible over HTTP)
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    # Redirect all other HTTP traffic to HTTPS
    location / {
        return 301 https://$host$request_uri;
    }
}

# HTTPS server block
server {
    listen 443 ssl;
    http2 on;
    server_name ${DEPLOY_DOMAIN};

    # --- TLS Certificate Paths (Let's Encrypt / Certbot) ---
    ssl_certificate     /etc/letsencrypt/live/${DEPLOY_DOMAIN}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/${DEPLOY_DOMAIN}/privkey.pem;

    # --- TLS Protocol & Cipher Configuration ---
    # Mozilla Intermediate compatibility (TLS 1.2 + 1.3)
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
    ssl_prefer_server_ciphers off;

    # --- TLS Session Caching ---
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;

    # --- OCSP Stapling ---
    ssl_stapling on;
    ssl_stapling_verify on;
    resolver 1.1.1.1 8.8.8.8 valid=300s;
    resolver_timeout 5s;

